            {
                await runtime.Modules.Call(
                    context,
                    "erlang",
                    operation,
                    arguments
                );
            }
            catch (ErlangException exception)
            {
                Equal(exception.Reason, Term.A("badarg"));
                rejected++;
            }
        }

        return Term.A("done");
    });
    Equal(await process.Completion, Term.A("normal"));
    Check(rejected == 2);
}
);
