namespace Erlang.Compiler;

internal static class LexerDiagnostics
{
    public const string UnsupportedEscape = "Hex, control and octal escapes are not implemented yet";
    public const string UnterminatedQuotedLiteral = "Unterminated quoted literal";
    public const string IllegalQuotedUnicode = "Illegal Unicode character in quoted literal";
    public const string IllegalAtom = "Illegal atom name";
    public const string IllegalVariable = "Illegal variable name";
}

namespace Erlang.Differential;

public static class AtomNameDiagnosticCases
{
    private const int OverMaximumCharacters = 256;
    private const string Prefix = "-module(atom_name_lexer_diagnostic). -export([run/0]). run()->";
    private const string Supplementary = "\U00010000";

    public static IReadOnlyList<CompiledDiagnosticCase> All { get; } =
    [
        Case("quoted", "'" + new string('a', OverMaximumCharacters) + "'", DiagnosticCaseKind.IllegalAtomName),
        Case("bare", new string('a', OverMaximumCharacters), DiagnosticCaseKind.IllegalAtomName),
        Case("variable", new string('A', OverMaximumCharacters), DiagnosticCaseKind.IllegalVariableName),
        Case(
            "quoted-supplementary",
            "'" + string.Concat(Enumerable.Repeat(Supplementary, OverMaximumCharacters)) + "'",
            DiagnosticCaseKind.IllegalAtomName
        )
    ];

    private static CompiledDiagnosticCase Case(string name, string token, DiagnosticCaseKind kind) => new(
        "atom-name-lexer-diagnostic-" + name,
        Prefix + token + ".",
        token,
        Kind: kind
    );
}

namespace Erlang.Differential;

public static class AtomNameDiagnosticExpectations
{
    public const string Code = "ERL001";
    public const string IllegalAtomMessage = "Illegal atom name";
    public const string IllegalVariableMessage = "Illegal variable name";
    public const string IllegalTag = "illegal";
    public const string AtomTag = "atom";
    public const string VariableTag = "var";

    public static string Message(CompiledDiagnosticCase fixture) => fixture.Kind == DiagnosticCaseKind.IllegalVariableName
        ? IllegalVariableMessage : IllegalAtomMessage;

    public static int Offset(CompiledDiagnosticCase fixture) => fixture.Source.IndexOf(fixture.Variable, StringComparison.Ordinal);

    public static Term Outcome(CompiledDiagnosticCase fixture) => Term.Tuple(
        Term.A(OracleOutcomeTags.Failure),
        Term.List(Term.Tuple(
            Term.A(IllegalTag),
            Term.A(fixture.Kind == DiagnosticCaseKind.IllegalVariableName ? VariableTag : AtomTag)
        ))
    );
}

